using LightInDark.Abilities;
using LightInDark.Core;
using LightInDark.Game;
using LightInDark.Patches;
using LightInDark.UI;
using UnityEngine;

namespace LightInDark.Roles
{
    public class ExampleRole : DefinedRole
    {
        public ExampleRole() : base("示例角色", Color.Cyan) { }

        public override RuntimeRole CreateInstance(Player player)
        {
            return new ExampleRuntime(this, player);
        }
    }

    public class ExampleRuntime : RuntimeRole
    {
        public ExampleRuntime(DefinedRole definition, Player player) : base(definition, player) { }

        protected override void OnActivated()
        {
            LightLogger.Log($"[ExampleRuntime] 角色激活，玩家: {MyPlayer.Name}");
            // 添加一个示例能力
            AddAbility(new ExampleAbility(MyPlayer));
        }
    }
}
public class ExampleAbility : AbstractPlayerAbility
{

    public ExampleAbility(Player player) : base(player)
    {
        LightLogger.Log($"[ExampleAbility] 能力创建，玩家: {player.Name}");

        // 加载一个测试图标（如果没有，就用内置图标）
        Sprite icon = HudManager.Instance.KillButton.graphic.sprite;

        var button = AbilityButtonFactory.CreateNormal(this, MyPlayer)
            .SetLabel("隐身")
            .SetImage(icon)
            .BindKey(KeyCode.F)
            .SetCooldown(5f)
            .Build();

        button.OnClick = () =>
        {
            LightLogger.Log($"[Ability] 隐身能力被触发");

            MyPlayer.Control.CoSetName("Button 能力触发！我们是冠军！！！！！");
            PatchManager.SendLocalMessage("We are champion!");
            MyPlayer.Control.RpcStartMeeting(null);
            button.StartCoolDown();
        };

        LightLogger.Log("[ExampleAbility] 按钮创建完成");
    }

    public override void Release()
    {
        LightLogger.Log("[ExampleAbility] 释放能力");
        // 按钮会自动释放，因为我们绑定了寿命
        base.Release();
    }
}

namespace LightInDark.Game
{
    public static class GameEntityExtension
    {
        /// <summary>
        /// 将实体注册到当前游戏，并绑定到指定的寿命
        /// </summary>
        public static T Register<T>(this T entity, ILifespan lifespan) where T : IGameOperator
        {
            var game = GameManager.Instance;
            if (game != null && !game.IsDeadObject)
            {
                game.RegisterEntity(entity, lifespan);
            }
            return entity;
        }

        /// <summary>
        /// 将实体注册到当前游戏，并绑定到自身的寿命（即 entity 自身作为 ILifespan）
        /// </summary>
        public static T RegisterSelf<T>(this T entity) where T : IGameOperator, ILifespan
        {
            return entity.Register(entity);
        }
    }
}

using LightInDark.Events;
using LightInDark.UI;
using System.Collections.Generic;
using System.Linq;

namespace LightInDark.Game
{
    public class GameManager : SimpleLifespan, IGame
    {
        private static GameManager _instance;
        public static GameManager Instance => _instance ??= new GameManager();

        private List<IGameOperator> _entities = new();

        public Player LocalPlayer { get; private set; }

        private GameManager() { }

        public void Initialize()
        {
            _entities.Clear();
            if (PlayerControl.LocalPlayer != null)
            {
                LocalPlayer = new Player(PlayerControl.LocalPlayer);
                RegisterEntity(LocalPlayer, this);
            }
            foreach (var pc in PlayerControl.AllPlayerControls)
            {
                if (pc == PlayerControl.LocalPlayer) continue;
                var player = new Player(pc);
                RegisterEntity(player, this);
            }
        }

        public Player GetPlayer(byte playerId)
        {
            return _entities.OfType<Player>().FirstOrDefault(p => p.Control.PlayerId == playerId);
        }

        public IEnumerable<Player> AllPlayers => _entities.OfType<Player>();

        public void RegisterEntity(IGameOperator entity, ILifespan lifespan)
        {
            _entities.Add(entity);
        }

        public void UnregisterEntity(IGameOperator entity)
        {
            _entities.Remove(entity);
        }

        public void Update()
        {
            _entities.RemoveAll(e => e.IsDeadObject);
            foreach (var entity in _entities)
            {
                if (entity is ModAbilityButton button)
                    button.Update();
            }
        }

        public new void Release()
        {
            base.Release();
            _instance = null;
        }
    }
}

